const j = $json;
// ISO timestamps contain colons, which collide with our ':' delimited callback_data.
// Strip them out here; parsed back on the callback side by re-inserting them positionally.
let version = '';
if (j.recordVersion) {
  const d = new Date(j.recordVersion);
  if (!isNaN(d.getTime())) {
    version = d.toISOString().replace(/[:]/g, '');
  }
}
const cur = j.currency || 'INR';
const fmtVal = v => (cur === 'INR' ? `\u20b9${Number(v).toLocaleString('en-IN')}` : `${cur} ${Number(v).toLocaleString('en-US')}`);
const authorizedUserId = j.userId || j.chatId || '';
const base = `appr:${j.leadId}:${j.field}:${j.newValue}:${version}:${authorizedUserId}`;
const label = j.field === 'status' ? `${j.oldValue} \u2192 ${j.newValue}` : `${fmtVal(j.oldValue)} \u2192 ${fmtVal(j.newValue)}`;
return [{ json: {
  chatId: j.chatId,
  businessName: j.businessName,
  fieldLabel: j.field === 'status' ? 'Status change' : 'Deal value change',
  changeLabel: label,
  callbackApprove: `${base}:A`,
  callbackReject: `${base}:R`
} }];

const j = $json;
const parts = (j.callbackData || '').split(':');
let leadId, field, newValue, versionStr, authorizedUserId, decision;
if (parts.length >= 7) {
  leadId = Number(parts[1]);
  field = parts[2];
  newValue = parts[3];
  versionStr = parts[4] || '';
  authorizedUserId = parts[5];
  decision = parts[6];
} else {
  leadId = Number(parts[1]);
  field = parts[2];
  newValue = parts[3];
  versionStr = parts[4] || '';
  authorizedUserId = '';
  decision = parts[5];
}
const version = versionStr.replace(/T(\d{2})(\d{2})(\d{2})/, 'T$1:$2:$3');
const callerUserId = j.fromId || j.userId || (j.callbackQuery && j.callbackQuery.from ? j.callbackQuery.from.id : null);
return [{ json: {
  leadId, field, newValue, version, authorizedUserId, callerUserId, decision,
  chatId: j.chatId, callbackQueryId: j.callbackQueryId, messageId: j.messageId
} }];

const p = $('Parse Approval Callback').first().json;
const cur = $json;
const notFound = !cur || !cur.id;
const curVersion = (cur && cur.updated_at) ? new Date(cur.updated_at).toISOString() : '';
const unauthorized = Boolean(p.authorizedUserId && p.callerUserId && String(p.authorizedUserId) !== String(p.callerUserId));
let expired = false;
if (p.version) {
  const parsedTime = new Date(p.version).getTime();
  if (!isNaN(parsedTime) && Date.now() - parsedTime > 15 * 60 * 1000) {
    expired = true;
  }
}
const isStale = notFound || (!unauthorized && !expired && curVersion && curVersion !== p.version);
const stale = unauthorized || expired || notFound || isStale;
const failureReason = unauthorized ? 'UNAUTHORIZED' : (expired ? 'EXPIRED' : (notFound ? 'NOT_FOUND' : (isStale ? 'STALE' : 'NONE')));
return [{ json: { ...p, currentBusinessName: cur ? cur.business_name : '', notFound, unauthorized, expired, isStale, stale, failureReason } }];

const j = $json;
let text;
if (j.failureReason === 'UNAUTHORIZED') {
  text = `\u26d4 <b>Unauthorized</b>: You do not have permission to approve or reject this change.`;
} else if (j.failureReason === 'EXPIRED') {
  text = `\u23f0 <b>Expired</b>: This approval request has expired (15-minute limit). Please re-run the command.`;
} else if (j.failureReason === 'NOT_FOUND') {
  text = `\u26a0\ufe0f This lead no longer exists (it may have been deleted). No update made.`;
} else {
  text = `\u26a0\ufe0f <b>Conflict</b>: This record was already updated or modified concurrently. No changes applied.`;
}
return [{ json: { chatId: j.chatId, callbackQueryId: j.callbackQueryId, messageId: j.messageId, text } }];

const original = $('Check Staleness').item.json;
const j = $json;
return [{
  json: {
    chatId: original.chatId,
    callbackQueryId: original.callbackQueryId,
    messageId: original.messageId,
    text: `❌ Change rejected for <b>${original.currentBusinessName}</b>. No update made.`
  }
}];

const original = $('Check Staleness').item.json;
const j = $json;
if (!j || !j.id) {
  return [{
    json: {
      chatId: original.chatId,
      callbackQueryId: original.callbackQueryId,
      messageId: original.messageId,
      text: `\u26a0\ufe0f Record was modified concurrently. Approval rejected.`
    }
  }];
}
return [{
  json: {
    chatId: original.chatId,
    callbackQueryId: original.callbackQueryId,
    messageId: original.messageId,
    text: `✅ Approved. <b>${original.currentBusinessName}</b> updated.`
  }
}];
